import React from 'react';

function InstructorSection() {
    const credentials = [
        {
            icon: (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M22 10v6M2 10l10-5 10 5-10 5z"></path>
                    <path d="M6 12.5V16a6 6 0 0 0 12 0v-3.5"></path>
                </svg>
            ),
            text: "Researcher in intonation & speech science"
        },
        {
            icon: (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor" stroke="none">
                    <path d="M12 1c-6.338 0-12 4.226-12 10.007 0 2.05.739 4.063 2.047 5.625l-1.047 3.368c-.114.363.07.751.424.887.086.034.177.051.267.051.272 0 .531-.155.651-.418l1.391-3.047c2.494 1.636 5.518 2.535 8.267 2.535 6.338 0 12-4.226 12-10.008 0-5.782-5.662-10.007-12-10.007zm-4 11c-.552 0-1-.448-1-1s.448-1 1-1 1 .448 1 1-.448 1-1 1zm4 0c-.552 0-1-.448-1-1s.448-1 1-1 1 .448 1 1-.448 1-1 1zm4 0c-.552 0-1-.448-1-1s.448-1 1-1 1 .448 1 1-.448 1-1 1z" opacity=".4" />
                    <path d="M16 11c-6.338 0-12 4.226-12 10.007 0 2.05.739 4.063 2.047 5.625l-1.047 3.368c-.114.363.07.751.424.887.086.034.177.051.267.051.272 0 .531-.155.651-.418l1.391-3.047c2.494 1.636 5.518 2.535 8.267 2.535 6.338 0 12-4.226 12-10.008 0-5.782-5.662-10.007-12-10.007zm-4 11c-.552 0-1-.448-1-1s.448-1 1-1 1 .448 1 1-.448 1-1 1zm4 0c-.552 0-1-.448-1-1s.448-1 1-1 1 .448 1 1-.448 1-1 1zm4 0c-.552 0-1-.448-1-1s.448-1 1-1 1 .448 1 1-.448 1-1 1z" transform="translate(-2, -4)" />
                </svg>
            ),
            text: "Actor-based vocal techniques"
        },
        {
            icon: (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"></path>
                    <path d="M19 10v1a7 7 0 0 1-14 0v-1"></path>
                    <line x1="12" y1="19" x2="12" y2="23"></line>
                    <line x1="8" y1="23" x2="16" y2="23"></line>
                </svg>
            ),
            text: "Used by speakers, educators & leaders"
        },
        {
            icon: (
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 19l7-7 3 3-7 7-3-3z"></path>
                    <path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z"></path>
                    <path d="M2 2l7.586 7.586"></path>
                    <circle cx="11" cy="11" r="2"></circle>
                </svg>
            ),
            text: "Author of Voice Control"
        }
    ];

    return (
        <section className="bg-white py-12 md:py-24 lg:py-0 lg:h-[900px] flex items-center overflow-hidden">
            <div className="container mx-auto max-w-[1446px] px-4 lg:px-8">
                {/* Inner Content Container - 1366px */}
                {/* items-start to ensure text starts where the image starts */}
                <div className="max-w-[1366px] mx-auto flex flex-row items-start gap-4 sm:gap-10 lg:gap-16 xl:gap-24">
                    {/* Left side: Video/Image - Fixed dimensions 590x672 */}
                    <div className="flex-[0.85] sm:flex-1 flex justify-start">
                        <div className="relative w-full max-w-[180px] xs:max-w-[220px] sm:max-w-[350px] md:max-w-[480px] lg:max-w-[590px] h-[205px] xs:h-[250px] sm:h-[400px] md:h-[546px] lg:h-[672px] rounded-[16px] xs:rounded-[24px] md:rounded-[40px] overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.12)] bg-gray-100 group cursor-pointer border border-gray-100">
                            <img
                                src="/images/2.png"
                                alt="Sevil Velsha - Voice Coach"
                                className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                            />
                            {/* Play Button Overlay */}
                            <div className="absolute inset-0 flex items-center justify-center">
                                <div className="w-12 h-12 xs:w-16 xs:h-16 md:w-20 lg:w-24 md:h-20 lg:h-24 bg-white/30 backdrop-blur-md rounded-full flex items-center justify-center border border-white/50 group-hover:bg-white/40 transition-all duration-300">
                                    <div className="w-0 h-0 border-t-[8px] xs:border-t-[10px] md:border-t-[14px] border-t-transparent border-l-[14px] xs:border-l-[18px] md:border-l-[26px] border-l-white border-b-[8px] xs:border-b-[10px] md:border-b-[14px] border-b-transparent ml-1.5 xs:ml-2"></div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Right side: Content - max-width 641px as per Figma */}
                    <div className="flex-[1.15] sm:flex-1 w-full text-left lg:max-w-[641px]">
                        <h2 className="font-serif text-[18px] xs:text-[22px] sm:text-3xl md:text-4xl lg:text-[54px] lg:leading-[70px] font-bold text-[#000000] mb-3 xs:mb-6 md:mb-8 tracking-normal">
                            Meet the Voice Behind the Method
                        </h2>

                        <div className="space-y-3 xs:space-y-4 md:space-y-[1px] mb-4 xs:mb-8 md:mb-10 lg:max-w-[415px]">
                            {credentials.map((item, index) => (
                                <div key={index} className="flex items-center gap-2 xs:gap-3 md:gap-4 text-[#212529] font-poppins text-[10px] xs:text-[12px] sm:text-base lg:text-[19.5px] lg:leading-[29.3px]">
                                    <span className="text-guarantee-green flex-shrink-0 w-4 h-4 xs:w-5 xs:h-5 md:w-[24px] md:h-[24px] flex items-center justify-center">
                                        {item.icon}
                                    </span>
                                    <span className="opacity-90">{item.text}</span>
                                </div>
                            ))}
                        </div>

                        <div className="space-y-3 xs:space-y-6 md:space-y-8">
                            <p className="font-poppins text-[9px] xs:text-[11px] sm:text-base md:text-[18px] lg:text-[20px] leading-snug xs:leading-relaxed text-gray-text max-w-2xl opacity-90">
                                Sevil Velsha is a voice coach, PhD, and educator dedicated to helping people unlock authority, calm, and presence through their voice. With a background in linguistics, intonation research, and stage performance, she bridges science and art to teach voice control that feels natural, grounded, and powerful.
                            </p>

                            <p className="font-poppins text-[9px] xs:text-[11px] sm:text-base md:text-[18px] lg:text-[20px] font-semibold italic text-heading-dark leading-snug xs:leading-relaxed border-l-[2px] xs:border-l-[3px] md:border-l-4 border-guarantee-green/40 pl-3 xs:pl-4 md:pl-6 max-w-2xl">
                                Her work proves one truth: your voice is not just sound — it is presence made audible.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
}

export default InstructorSection;
